const icon=(n,cls='')=>`<svg class="ico ${cls}" viewBox="0 0 24 24" aria-hidden="true">${I[n]||I.grid}</svg>`;
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const DBKEY='zhixu_classroom_demo_v3';
const dateISO=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const addDate=(s,n)=>{let d=new Date(s+'T12:00:00');d.setDate(d.getDate()+n);return dateISO(d)};
const dayNo=s=>(new Date(s+'T12:00:00').getDay()+6)%7;
const dateText=s=>{let d=new Date(s+'T12:00:00');return `${d.getMonth()+1}月${d.getDate()}日`};
